    sq: { ref: "pow" }, cube: { ref: "pow" },
    sqrt: { title: "Square root by guess and improve (Newton’s method)", tool: "sqrt",
      intro: "Guess. Divide the number by your guess. Average the guess and the answer. That average is a better guess. Repeat.",
      steps: ["Make a guess g.", "Work out n ÷ g.", "New guess = (g + n ÷ g) ÷ 2.", "Repeat until it stops changing."] },
